PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(org_id TEXT NOT NULL REFERENCES organizations(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('admin','catalog','purchasing','warehouse','sales','viewer')),PRIMARY KEY(org_id,user_id));
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),sku TEXT NOT NULL,name TEXT NOT NULL,unit TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','inactive')),reorder_threshold INTEGER NOT NULL DEFAULT 0 CHECK(reorder_threshold>=0),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,UNIQUE(org_id,sku));
CREATE TABLE IF NOT EXISTS warehouses(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),code TEXT NOT NULL,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),UNIQUE(org_id,code));
CREATE TABLE IF NOT EXISTS suppliers(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),name TEXT NOT NULL,email TEXT NOT NULL,lead_days INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS supplier_products(supplier_id TEXT REFERENCES suppliers(id),product_id TEXT REFERENCES products(id),supplier_sku TEXT NOT NULL,cost_cents INTEGER NOT NULL CHECK(cost_cents>=0),PRIMARY KEY(supplier_id,product_id));
CREATE TABLE IF NOT EXISTS stock_levels(org_id TEXT NOT NULL,product_id TEXT NOT NULL REFERENCES products(id),warehouse_id TEXT NOT NULL REFERENCES warehouses(id),on_hand INTEGER NOT NULL DEFAULT 0 CHECK(on_hand>=0),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=on_hand),version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(product_id,warehouse_id));
CREATE TABLE IF NOT EXISTS stock_movements(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,product_id TEXT NOT NULL,warehouse_id TEXT NOT NULL,quantity_delta INTEGER NOT NULL CHECK(quantity_delta<>0),type TEXT NOT NULL,source_type TEXT NOT NULL,source_id TEXT NOT NULL,actor_id TEXT NOT NULL,reason TEXT,created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS immutable_movements_update BEFORE UPDATE ON stock_movements BEGIN SELECT RAISE(ABORT,'stock movements are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_movements_delete BEFORE DELETE ON stock_movements BEGIN SELECT RAISE(ABORT,'stock movements are immutable'); END;
CREATE TABLE IF NOT EXISTS purchase_orders(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,supplier_id TEXT NOT NULL,warehouse_id TEXT NOT NULL,number TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL,UNIQUE(org_id,number));
CREATE TABLE IF NOT EXISTS purchase_lines(id TEXT PRIMARY KEY,purchase_id TEXT NOT NULL REFERENCES purchase_orders(id),product_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),received INTEGER NOT NULL DEFAULT 0 CHECK(received>=0 AND received<=quantity),unit_cost_cents INTEGER NOT NULL CHECK(unit_cost_cents>=0));
CREATE TABLE IF NOT EXISTS sales_orders(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,warehouse_id TEXT NOT NULL,customer_name TEXT NOT NULL,state TEXT NOT NULL,total_cents INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sales_lines(id TEXT PRIMARY KEY,sales_id TEXT NOT NULL REFERENCES sales_orders(id),product_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),shipped INTEGER NOT NULL DEFAULT 0 CHECK(shipped>=0 AND shipped<=quantity),unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>=0));
CREATE TABLE IF NOT EXISTS reservations(id TEXT PRIMARY KEY,sales_line_id TEXT NOT NULL,warehouse_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),state TEXT NOT NULL CHECK(state IN('active','released','consumed')));
CREATE TABLE IF NOT EXISTS shipments(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,sales_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS shipment_lines(shipment_id TEXT NOT NULL,product_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(shipment_id,product_id));
CREATE TABLE IF NOT EXISTS transfers(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,product_id TEXT NOT NULL,source_warehouse_id TEXT NOT NULL,destination_warehouse_id TEXT NOT NULL,quantity INTEGER NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS returns(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,shipment_id TEXT NOT NULL,product_id TEXT NOT NULL,quantity INTEGER NOT NULL,disposition TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency(org_id TEXT NOT NULL,scope TEXT NOT NULL,key TEXT NOT NULL,response TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(org_id,scope,key));
CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,metadata TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,type TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,available_at TEXT NOT NULL,dedupe_key TEXT UNIQUE,last_error TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_products_search ON products(org_id,status,name,sku);
CREATE INDEX IF NOT EXISTS idx_movements_ledger ON stock_movements(org_id,product_id,warehouse_id,created_at,id);
CREATE INDEX IF NOT EXISTS idx_jobs_poll ON jobs(state,available_at);
